594	
595	impl<T: UniformListDecoration + 'static> UniformListDecoration for Entity<T> {
596	    fn compute(
597	        &self,
598	        visible_range: Range<usize>,
599	        bounds: Bounds<Pixels>,
600	        scroll_offset: Point<Pixels>,
601	        item_height: Pixels,
602	        item_count: usize,
603	        window: &mut Window,
604	        cx: &mut App,
605	    ) -> AnyElement {
606	        self.update(cx, |inner, cx| {
607	            inner.compute(
608	                visible_range,
609	                bounds,
610	                scroll_offset,
611	                item_height,
612	                item_count,
613	                window,
614	                cx,
615	            )
616	        })
617	    }
618	}
